mapper.sql:
FROM ecommerce_user u
LEFT JOIN user_profile_summary p ON p.user_id = u.id
LEFT JOIN user_segment s ON s.user_id = u.id

    u.user_code LIKE CONCAT('%', #{keyword}, '%')
    AND s.segment_code = #{segmentCode}
    AND u.province = #{province}
    AND COALESCE(p.total_payment_amount, 0) >= #{minAmount}
    AND COALESCE(p.total_payment_amount, 0) <= #{maxAmount}


        AND EXISTS (SELECT 1 FROM user_profile_tag ut2
                    JOIN profile_tag_definition td2 ON td2.id = ut2.tag_id
                    WHERE ut2.user_id = u.id AND td2.tag_code = #{tagCode}
                      AND FIND_IN_SET(ut2.tag_value, #{tagValue}))

mapper.select:
SELECT  
WHERE u.id IN #{id}
ORDER BY COALESCE(ps.total_payment_amount, 0) DESC

SELECT ut.tag_value AS label, COUNT(DISTINCT ut.user_id) AS cnt FROM user_profile_tag ut
JOIN profile_tag_definition td ON td.id = ut.tag_id AND td.tag_code = #{tagCode}
WHERE ut.user_id IN #{id}
/* 过滤画像任务兜底标签（脏数据，防止英文 Unknown/空白/null 出现在对比结果里） */
AND ut.tag_value IS NOT NULL AND ut.tag_value != '' AND ut.tag_value NOT IN ('Unknown', 'null', 'NULL')
GROUP BY ut.tag_value ORDER BY cnt DESC LIMIT 10
